/*
 * build_info.h -- which build is this, and for what? (both targets)
 *
 * A tester's screenshot or log has to answer that on its own; asking costs a
 * round trip and is often unanswerable later. src/build_info.c holds the
 * strings: the commit from include/swos_build.h (generated by
 * scripts/gen_build_info.sh) and the platform from the compiler's own macros.
 *
 * Shown in four places, so at least one survives however a report arrives:
 * the main menu's bottom line, the SDL window title, the [build] line in
 * SWOS.log, and --version.
 */
#ifndef BUILD_INFO_H
#define BUILD_INFO_H

/* Single source of truth for the user-facing release/build number. */
/* v274: keep v273 CE VIEW RESULT and VIEW COMPETITION fixes unchanged.
 * Ensure C declarations precede OG board visibility callback; employed
 * VIEW WORLD picker carries selected country into existing CE read-only
 * standings projection (no new UI, cup changes, or result writer).
 * Windows GCC/gameplay, 23+ native table and CAR CONTINUE not yet proven. */
/* v275: CE2627 league board follows the ORIGINAL OG career buttons:
 * manager fixture MATCH + RESULT; CPU fixtures of the manager's round one
 * by one with VIEW RESULT (OG quick, same CE order, RAM CPU batch), then
 * NEXT MATCH; EXIT when the round is complete. FORWARD stops before the
 * round. Windows GCC/gameplay NOT PROVEN. */
/* v276: CE2627 board as in the OG video: PLAY MATCH opens on the manager
 * fixture (round fixtures before it completed once by OG quick and shown
 * only in the table); after it NEXT MATCH / VIEW RESULT one by one; NEXT
 * MATCH after the last returns to the career menu. A nested OG menu
 * (lineup) no longer runs legacy board code or draws the all-zero original
 * table during a CE action (crash after MATCH, zero-table flash).
 * Windows GCC/gameplay NOT PROVEN. */
/* v277: board RESULT on the manager fixture opens the ORIGINAL OG team
 * screen (VIEW RESULT / EXIT) before the OG quick result, as in OG career;
 * EXIT cancels before CAR CLAIMED. Windows GCC/gameplay NOT PROVEN. */
/* v278: CE board fills the OG league team-id list, so STATS -> VIEW
 * SQUADS no longer PANICs on VerifyTeamLoaded(0). Manager quick VIEW
 * RESULT: one CAR save AFTER the result (no CLAIMED save); 50 Hz MATCH
 * keeps CLAIMED + COMPLETED. Windows NOT PROVEN. */
/* v279: after the manager's VIEW RESULT the CE board cursor starts on
 * EXIT (NEXT MATCH still visible). Windows NOT PROVEN. */
/* NOTE: the label 00.13.275 was used twice on 23/11/2026: commit ce8ba4e
 * (removal of 3 disabled #if 0 LWE blocks in expanded_world_live.c) and
 * the CE board work v275-v279 above (commit 2c7d5e1). */
/* v280: CE fixture dates on ANY civil day. New pure planner
 * (expanded_universal_date_planner.c) + data
 * data_json/worlds/2627/competitions/league_calendar.json (window,
 * SUN rounds, WED only if needed, rest 3, breaks). OG native phases no
 * longer date CE fixtures (first-day-of-phase retired); missing/impossible
 * calendar data fails closed. Same CE clock (scheduler.clock.day_index),
 * LWE cursor only a mirror. Isolated tests PASS; Windows NOT PROVEN. */
/* v281: CE calendar screen: the blue cursor row is ALWAYS the line of the
 * date shown now (civil today), not the next unplayed match. If no match or
 * weekly stop falls on today, a no-match line (SEASON BREAK wording) is
 * added for today inside the season span; viewport recentres on it daily.
 * Render only; no clock/fixture/CAR change. User-approved 23/11/2026.
 * Windows NOT PROVEN. */
/* v282: LWE clock dependency removed from the CE (WORLD2627). The CE
 * registry clock (scheduler.clock.day_index) is the ONLY world clock:
 * ExpandedUniversalLive_Today/TodayIndex; expanded_universal_live.c no
 * longer calls ExpandedWorldLive_CalendarState/AdvanceToDate; LWE became a
 * passive mirror fed through ExpandedWorldLive_SetClockProvider (its
 * AdvanceToDate is refused while the CE is active; CalendarState returns
 * the CE day even without LWE state). Coordinator check no longer needs
 * LWE clubs. Also: CE board fire-reset (NEXT MATCH) from the 23/11 diag.
 * NOT removed: LWE importer still feeds the CE club/league catalogue.
 * Windows gameplay/CONTINUE NOT PROVEN. */
/* v283: v282 clock hardening. (1) LWE mirror is EXACT: equals the CE day
 * also backwards when LWE holds no fixtures, and CalendarState always reports
 * the CE day when the CE is active. (2) GCC constructor replaced by explicit
 * ExpandedUniversalLive_RegisterClock() called from ExpandedUniversal_CarBegin
 * and _CarRestore. (3) CAR load drops a stale CE registry BEFORE the LWE
 * state is read (save_format_json.c), so an old career clock can never leak
 * into a restored one. New isolated test run_test_expanded_world_clock_mirror.sh.
 * Windows gameplay/CONTINUE NOT PROVEN. */
#define SWOS_EXPANDED_VERSION "00.13.283"

/* "401ff14", or "401ff14-dirty" when tracked source differed from that commit
 * -- meaning the binary is NOT that commit. Lowercase, as git prints it. */
const char *Build_Id(void);

/* The commit's date, "2026-09-15". */
const char *Build_Date(void);

/* What this binary was built for: "linux x86-64", "windows x86-64",
 * "macos arm64", "amiga 68k" (or "amiga 68k aga"), "web", "switch".
 * The ONLY place the platform is decided -- don't detect it again elsewhere. */
const char *Build_Platform(void);

/* One line for a human: "OpenSWOS 401ff14 (2026-09-15, linux x86-64)".
 * Window title, SWOS.log and --version. */
const char *Build_Version(void);

/* Compact version label drawn on the title screen, e.g. "Build 0.10.51_01". */
const char *Build_DisplayVersion(void);

/* The same facts for drawing with the in-game font, which has no lowercase
 * glyphs: "BUILD DD74714  2026-09-15  LINUX X86-64". */
const char *Build_ScreenText(void);

#endif /* BUILD_INFO_H */
